"""SEN0401 chapter 1, text part E (version 1.2.0): the Nature branch (what kind of thing Bitcoin is) and the further concepts added to the Transfer, Address and Standards
sections. See sen0401_ch01_corpus_v1_2_0.py."""
from sen0401_ch01_common_v1_2_0 import W, Y, E, H, K, js, prog
_RULE = prog('''def accept(claim, height, fees):
    subsidy = (50 * 10**8) >> (height // 210000)
    return claim <= subsidy + fees
result = [accept(312_500_000, 840000, 0), accept(312_500_001, 840000, 0), accept(325_000_000, 840000, 12_500_000)]''')
_P2P = prog('''links = {'A': ['B', 'C'], 'B': ['A', 'D'], 'C': ['A', 'E'], 'D': ['B', 'F'], 'E': ['C', 'F'], 'F': ['D', 'E', 'G'], 'G': ['F']}
seen, frontier, rounds = {'A'}, {'A'}, 0
while len(seen) < len(links):
    frontier = {n for f in frontier for n in links[f]} - seen
    seen |= frontier; rounds += 1
result = rounds''')
_VIRT = prog('''txs = [('Joe', 'Alice', 100_000), ('Alice', 'Eve', 30_000), ('Joe', 'Eve', 5_000)]
def balance(who): return sum(a for f, t, a in txs if t == who) - sum(a for f, t, a in txs if f == who)
result = (balance('Alice'), balance('Eve'))''')
_CHAN = prog('''onchain, a, b = 2, 60_000, 40_000
for _ in range(100):
    a, b = a - 10, b + 10
result = (a, b, a + b, onchain)''')
_LN = prog('''channels = {('Alice', 'Bob'), ('Bob', 'Carol'), ('Carol', 'Dave')}
nbr = {}
for x, y in channels: nbr.setdefault(x, []).append(y); nbr.setdefault(y, []).append(x)
path, frontier = {'Alice': ['Alice']}, ['Alice']
while 'Dave' not in path:
    nxt = []
    for x in frontier:
        for y in nbr[x]:
            if y not in path: path[y] = path[x] + [y]; nxt.append(y)
    frontier = nxt
result = (path['Dave'], len(path['Dave']) - 1, ('Alice', 'Dave') in channels)''')
